/bin/bash -lc "node check.js && node <<'NODE'
const assert = require('node:assert/strict');
const { parse_port } = require('./logic');
for (const value of [undefined, null, 80, true, {}, ['80'], '80\\n', '80\\r', '80 ', '+80', '1.0', '1e2', '0x50', '\\t80', '000', '9'.repeat(400)]) {
  assert.equal(parse_port(value), null);
}
for (const [input, expected] of [['00001', 1], ['00065535', 65535], ['0'.repeat(400) + '80', 80]]) {
  assert.equal(parse_port(input), expected);
}
for (let port = 1; port <= 65535; port++) {
  assert.equal(parse_port(String(port)), port);
}
console.log('Existing checks and additional input/boundary verification passed.');
NODE"

